import {createBalanceBoard} from './balance-view.js';
import {initialBuild} from './balance-lab.js';
import {createRobotBoard,drawWorkshopMap} from './robot-board.js';
import {initialRobot} from './robot-lab.js';
import * as THREE from 'three';
import {HOME_ZONES} from './layout.js';
import {BLOCKS,initialKitchen,initialCode,initialBlocks} from './play-state.js';
export function blockPositions(state){const out={},ids=Object.keys(BLOCKS);for(const[i,id]of ids.entries())out[id]={x:-1.35+i*1.35,y:.16+BLOCKS[id].height/2,z:2.75};let y=.16;for(const id of state.stack){out[id]={x:0,y:y+BLOCKS[id].height/2,z:1.9};y+=BLOCKS[id].height;}if(state.pending){const id=state.pending,from=out[id],t=Math.min(1,state.elapsed/.35),q=t*t*(3-2*t);out[id]={x:from.x*(1-q),y:from.y*(1-q)+(y+BLOCKS[id].height/2)*q+Math.sin(Math.PI*q)*.35,z:from.z*(1-q)+1.9*q};}return out;}
export function drawRobot(ctx,s){const w=500,cell=88,ox=30,oy=28;ctx.fillStyle='#e8f0dd';ctx.fillRect(0,0,w,w);for(let z=0;z<5;z++)for(let x=0;x<5;x++){ctx.fillStyle=(x+z)%2?'#dce7d2':'#f5f2dc';ctx.fillRect(ox+x*cell,oy+z*cell,cell-3,cell-3);}ctx.fillStyle='#c29739';ctx.font='52px "Dormi Gentle Pen", sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('★',ox+3.5*cell,oy+1.5*cell);const x=ox+(s.x+.5)*cell,y=oy+(s.z+.5)*cell;ctx.save();ctx.translate(x,y);ctx.rotate(s.heading*Math.PI/2);ctx.fillStyle='#648d92';ctx.beginPath();ctx.moveTo(0,-29);ctx.lineTo(25,22);ctx.lineTo(0,11);ctx.lineTo(-25,22);ctx.closePath();ctx.fill();ctx.restore();}
export function buildHomeRoom(def,kit,{shell=true,progress}={}){
 const {root,box,sphere,cylinder,label,mat}=kit;const existing=new Set(root.children);const named=(m,name)=>{m.name=name;return m;};
 const floor=HOME_ZONES[def.id].floor,w=floor.maxX-floor.minX,d=floor.maxZ-floor.minZ;
 if(shell){box(w,.30,d,'#e7d4b5',0,-.14,0,.04);box(w,2.6,.15,'#e9e0cc',0,1.3,floor.minZ,.03);}
 let state,kitchen=null,screen=null,robot=null,blocks=null,lab=null,labMount=null,labState=null,balance=null;
 if(def.id==='homeKitchen'){
  for(const x of [-1.1,0,1.1]){box(1.04,1,.99,'#c8bb97',x,.52,-2.25,.05);box(.87,.67,.045,'#e3d5af',x,.58,-1.73,.03);box(.32,.065,.09,'#8a9f90',x,.86,-1.66,.02);}
  box(3.38,.15,1.28,'#f4e8cd',0,1.08,-2.25,.06);const bowlMaterial=mat('#d6a07c');bowlMaterial.side=THREE.DoubleSide;const rim=named(new THREE.Mesh(new THREE.CylinderGeometry(.47,.31,.30,24,1,true),bowlMaterial),'homeKitchen.bowl');rim.position.set(-.35,1.305,-2.12);root.add(rim);const bowlBase=cylinder(.31,.31,.035,'#d6a07c',-.35,1.175,-2.12);const lip=new THREE.Mesh(new THREE.TorusGeometry(.448,.025,8,24),bowlMaterial);lip.rotation.x=Math.PI/2;lip.position.set(-.35,1.455,-2.12);root.add(lip);const yogurt=cylinder(.40,.34,.025,'#fff4dc',-.35,1.43,-2.12);const fruits=[];for(const[i,c]of ['#d78a79','#e5bc66','#b5c38e'].entries())fruits.push(sphere(.115,c,-.57+i*.21,1.485,-2.12,.9,.65,.9));
  const spoon=new THREE.Group();spoon.position.set(-.35,1.5,-2.12);root.add(spoon);named(box(.07,.045,.55,'#aa8e69',0,0,.08,.02,spoon),'homeKitchen.spoon');sphere(.105,'#aa8e69',0,-.025,-.23,.8,.25,1.3,spoon);
  const plate=cylinder(.49,.49,.06,'#b4cbc1',.95,1.185,-2.12);const served=cylinder(.34,.28,.17,'#eed7b2',.95,1.30,-2.12);const garnish=sphere(.12,'#d78a79',.95,1.40,-2.12,1,.6,1);
  box(1.22,2.2,1.20,'#a5c0bd',-3.1,1.12,-2.25,.08);for(const y of [.68,1.8])box(.075,.46,.09,'#eae1c9',-2.66,y,-1.59,.02);box(1.2,.035,.025,'#789a96',-3.1,1.46,-1.635,.01);
  box(1.03,1.2,1,'#d3bb94',3.15,.62,-2.6,.04);cylinder(.20,.15,.35,'#c28f72',3.15,1.38,-2.6);sphere(.29,'#88aa7e',3.15,1.73,-2.6,1,.75,1);label('계량 · 비율 · 레시피 실험',.05,2.44,-3.36,3.7);kitchen={yogurt,fruits,spoon,served,garnish,rim,bowlBase,lip,plate};state=initialKitchen();
 }else if(def.id==='homeStudy'){
  box(3.2,.15,1.3,'#d1b187',0,.99,2.45,.06);for(const x of [-1.35,1.35])for(const z of [2,2.9])box(.12,.94,.12,'#89a9a3',x,.48,z,.02);
  box(.85,.10,.45,'#6b8587',0,1.13,2.68,.035);box(.13,.43,.13,'#6b8587',0,1.34,2.70,.025);named(box(1.83,1.3,.18,'#63888a',0,1.88,2.73,.055),'homeStudy.monitor');
  // Both faces carry the same readable grid; the room and approach stay useful from either camera side.
  const canvas=typeof document!=='undefined'?document.createElement('canvas'):null;let texture;if(canvas){canvas.width=500;canvas.height=500;texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;}
  for(const side of [-1,1]){const m=texture?new THREE.Mesh(new THREE.PlaneGeometry(1.63,1.12),new THREE.MeshBasicMaterial({map:texture})):box(1.63,1.12,.015,'#dce7d2',0,1.88,2.73+side*.101,.005);if(texture){m.position.set(0,1.88,2.73+side*.101);if(side<0)m.rotation.y=Math.PI;root.add(m);}}
  if(!texture){for(let z=0;z<5;z++)for(let x=0;x<5;x++)named(box(.285,.208,.01,(x+z)%2?'#e3ecd7':'#f5f1dd',(x-2)*.30,2.32-z*.22,2.838,.003),`homeStudy.grid.${x}.${z}`);const starShape=new THREE.Shape();for(let i=0;i<10;i++){const a=Math.PI/2+i*Math.PI/5,r=i%2?.033:.077;i?starShape.lineTo(Math.cos(a)*r,Math.sin(a)*r):starShape.moveTo(Math.cos(a)*r,Math.sin(a)*r);}starShape.closePath();const goal=new THREE.Mesh(new THREE.ShapeGeometry(starShape),new THREE.MeshBasicMaterial({color:'#c29739'}));goal.position.set(.3,2.10,2.847);root.add(goal);const triangle=new THREE.Shape();triangle.moveTo(0,.066);triangle.lineTo(-.055,-.05);triangle.lineTo(0,-.025);triangle.lineTo(.055,-.05);triangle.closePath();robot=named(new THREE.Mesh(new THREE.ShapeGeometry(triangle),new THREE.MeshBasicMaterial({color:'#648d92'})),'homeStudy.robot');robot.position.z=2.851;root.add(robot);}
  box(1.25,.065,.42,'#e6e4cf',0,1.1,2.03,.025);for(let row=0;row<3;row++)for(let col=0;col<10;col++)box(.092,.025,.072,'#91aaa0',-.52+col*.115,1.145,1.9+row*.10,.008);
  const cable=new THREE.CatmullRomCurve3([new THREE.Vector3(.62,1.09,2.03),new THREE.Vector3(1.12,1.09,2.42),new THREE.Vector3(.15,1.15,2.69)]);root.add(new THREE.Mesh(new THREE.TubeGeometry(cable,12,.025,5,false),new THREE.MeshStandardMaterial({color:'#758e84'})));
  box(1.1,.12,1.08,'#aac2b1',0,.56,1.15,.07);box(1.1,.64,.13,'#90b0a4',0,.97,.64,.06);for(const x of [-.4,.4])for(const z of [.70,1.56])box(.08,.5,.08,'#8ba69a',x,.26,z,.015);
  box(1,1.55,.9,'#c1b08e',-2.9,.79,2.9,.04);for(let i=0;i<4;i++)box(.14,.46,.35,['#d69a84','#dfc073','#98b2b0','#a7b98e'][i],-3.2+i*.2,1.72,2.9,.015);label('명령이 만드는 길',0,3.0,3.55,3.0);
  // The same teal arrow from the coding board, made into a tiny shelf toy.
  const toy=named(new THREE.Group(),'homeStudy.shelf-robot');toy.position.set(-2.9,1.58,2.56);root.add(toy);const arrow=new THREE.Shape();arrow.moveTo(0,.59);arrow.lineTo(.23,.15);arrow.lineTo(0,.25);arrow.lineTo(-.23,.15);arrow.closePath();const body=new THREE.Mesh(new THREE.ExtrudeGeometry(arrow,{depth:.16,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:2,steps:1}),mat('#648d92'));body.position.z=-.08;toy.add(body);for(const x of[-.09,.09]){sphere(.034,'#fff7df',x,.37,-.115,1,1,.45,toy);sphere(.018,'#294f56',x,.37,-.134,1,1,.5,toy);const wheel=cylinder(.085,.085,.12,'#47666a',x,.075,0,toy);wheel.rotation.x=Math.PI/2;}
  screen={canvas,texture};state=initialCode();labMount=new THREE.Group();labMount.name='homeStudy.tabletop-lab';labMount.position.set(-1.04,1.075,2.23);labMount.scale.setScalar(.085);root.add(labMount);lab=createRobotBoard('first-route');labMount.add(lab.root);labState=initialRobot();
 }else{
  named(box(4.1,.14,2,'#c8c1a7',0,.08,2.3,.13),'homePlayroom.mat');const ring=new THREE.Mesh(new THREE.RingGeometry(.59,.64,32),new THREE.MeshBasicMaterial({color:'#fbefd3',side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(0,.157,1.9);root.add(ring);blocks={};for(const[id,b]of Object.entries(BLOCKS))blocks[id]=named(box(b.width,b.height,b.width,b.color,0,0,0,.045),'homePlayroom.block.'+id);
  box(1.2,1.12,1,'#d3b58c',-3,.58,2.85,.04);for(const x of [-3.3,-2.7]){sphere(.18,'#d7a482',x,1.30,2.85,1,.9,1);sphere(.11,'#efd9a2',x,1.55,2.85,1,1,1);}label('균형을 만드는 손',0,2.9,3.65,3.1);state=initialBlocks();
 }
 function update(next){state=next;if(kitchen){const filled=next.phase!=='empty',mixed=['mixed','served'].includes(next.phase),served=next.phase==='served';kitchen.yogurt.visible=filled&&!served;kitchen.yogurt.material.color.set(mixed?'#eed7b2':'#fff4dc');for(const f of kitchen.fruits)f.visible=filled&&!served;kitchen.spoon.visible=filled&&!served;kitchen.spoon.rotation.y=next.phase==='mixing'?next.elapsed*Math.PI*5:0;kitchen.spoon.position.x=-.35+(next.phase==='mixing'?Math.sin(next.elapsed*12)*.12:0);kitchen.served.visible=kitchen.garnish.visible=served;}if(screen?.canvas){drawRobot(screen.canvas.getContext('2d'),next);screen.texture.needsUpdate=true;}if(robot){robot.position.x=(next.x-2)*.30;robot.position.y=2.32-next.z*.22;robot.rotation.z=-next.heading*Math.PI/2;}if(blocks){const poses=blockPositions(next);for(const[id,m]of Object.entries(blocks)){m.position.set(poses[id].x,poses[id].y,poses[id].z);m.scale.setScalar(next.selected===id&&next.phase==='selected'?1.06:1);}}}
 if(def.id==='homeStudy'){const fixtureRoot=new THREE.Group();fixtureRoot.name='homeStudy.side-wall-fixtures';for(const child of [...root.children])if(!existing.has(child))fixtureRoot.add(child);fixtureRoot.rotation.y=-Math.PI/2;root.add(fixtureRoot);}
 function updateBuild(next){if(!blocks)return;if(!balance){balance=createBalanceBoard();balance.root.position.set(0,.17,2.3);balance.root.scale.setScalar(.35);root.add(balance.root);}for(const block of Object.values(blocks))block.visible=false;balance.update(next);}
 update(state);if(blocks&&progress?.homeBuild)updateBuild(initialBuild(progress.homeBuild.selected,progress.homeBuild.builds[progress.homeBuild.selected]??[]));return {updateBuild,get state(){return state;},update,screen,blocks,kitchen,updateLab(next,{snap=false}={}){if(!labMount)return;if(labState?.stageId!==next.stageId){lab.dispose();lab=createRobotBoard(next.stageId);labMount.add(lab.root);}labState=next;lab.update(next,{snap});if(screen?.canvas){drawWorkshopMap(screen.canvas.getContext('2d'),next);screen.texture.needsUpdate=true;}},tickLab(dt){lab?.tick(dt);},dispose(){balance?.dispose();balance=null;lab?.dispose();lab=null;}};
}
